input.command:
F=$(find . -name "*.py" -not -path "./.venv/*" -not -path "./.claude/*" -not -path "*/__pycache__/*" | sort)
echo "== print (excl. smoke test)"; grep -n "print(" $F | grep -v tests/
echo "== execute with f-string/concat"; grep -nE "execute(many)?\(\s*f?[\"'].*(\+|\{)" $F; grep -nE "f\"\"\"SELECT|f\"SELECT|f\"DELETE" $F
echo "== secrets/debug"; grep -nE "SECRET_KEY\s*=\s*['\"]|debug\s*=\s*True|DEBUG\"\]\s*=\s*True" $F
echo "== global"; grep -n "global " $F
echo "== broad except"; grep -n "except Exception\|except:" $F
echo "== senha in serializers"; grep -n "\"senha\"" $F | grep -v validators
echo "== layer imports"; grep -nE "^from (flask|views|controllers)" models/*.py; grep -nE "^(from|import) (sqlite3|database|views)" controllers/*.py
echo "== pyflakes-ish unused imports"; .venv/bin/python -m pyflakes --version >/dev/null 2>&1 && .venv/bin/python -m pyflakes $F || python3 - $F <<'EOF'
import ast, sys
for path in sys.argv[1:]:
    tree = ast.parse(open(path).read())
    names = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names: names[(a.asname or a.name).split(".")[0]] = node.lineno
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    src = open(path).read()
    for n, l in names.items():
        if n not in used and "__all__" not in src and not path.endswith("__init__.py"): print(f"{path}:{l} unused {n}")
EOF
wc -l $F | tail -1; echo; echo "$F" | wc -l

