G="grep -rnE --include=*.py --exclude-dir=.venv --exclude-dir=.claude --exclude-dir=__pycache__"
echo "== print (excl. tests)"; $G "print\(" . | grep -v "^./tests/"
echo "== SQL built with f-string/concat"; $G "execute(many)?\(" . | grep -E "\+ *[a-z]|f\"|f'" ; $G "f\"\"\"SELECT|f\"SELECT|f\"DELETE" .
echo "== secrets/debug literals"; $G "SECRET_KEY\s*=\s*['\"]|debug\s*=\s*True|DEBUG\"\]\s*=\s*True|secret_key\"" .
echo "== global"; $G "global " .
echo "== broad except"; $G "except Exception|except:" .
echo "== senha field outside validators/model internals"; $G "\"senha\"" . | grep -v validators
echo "== layer violations"; $G "^from (flask|views|controllers)|^import flask" models/; $G "^(from|import) (sqlite3|database|views)" controllers/
echo "== unused imports"; find . -name "*.py" -not -path "./.venv/*" -not -path "./.claude/*" -not -path "*/__pycache__/*" -not -name "__init__.py" -print0 | xargs -0 python3 -c '
import ast, sys
for path in sys.argv[1:]:
    tree = ast.parse(open(path).read())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names: imported[(a.asname or a.name).split(".")[0]] = node.lineno
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    for name, line in imported.items():
        if name not in used: print(f"{path}:{line} unused {name}")
'
echo "== size"; find . -name "*.py" -not -path "./.venv/*" -not -path "./.claude/*" -not -path "*/__pycache__/*" | wc -l; find . -name "*.py" -not -path "./.venv/*" -not -path "./.claude/*" -not -path "*/__pycache__/*" -print0 | xargs -0 wc -l | tail -1

